const LangContext = createContext(null);

export function LangProvider({ children }) {
  const [lang, setLang] = useState(
    () => localStorage.getItem('sowoccul_lang') || 'en'
  );
  const change = useCallback((l) => {
    setLang(l);
    localStorage.setItem('sowoccul_lang', l);
  }, []);
  const t = useCallback((key) => strings[lang][key] ?? strings.en[key] ?? key, [lang]);
  return (
    <LangContext.Provider value={{ lang, setLang: change, t }}>
      {children}
    </LangContext.Provider>
  );
}

export function useLang() {
  const ctx = useContext(LangContext);
  if (!ctx) throw new Error('useLang must be used within LangProvider');
  return ctx;
}
